@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap');

:root {
  --ink: #20263d;
  --muted: #8990a7;
  --purple: #6857e8;
  --purple-dark: #5545d1;
  --line: #e9eaf2;
  --surface: #ffffff;
  --background: #f5f6fb;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  background: linear-gradient(140deg, #f7f8fd 0%, #eff0fa 100%);
  font-family: 'DM Sans', sans-serif;
}
.app-shell { width: min(100% - 32px, 620px); margin: 0 auto; padding: 62px 0 28px; }
.todo-card { background: var(--surface); border: 1px solid rgba(224,225,237,.8); border-radius: 22px; box-shadow: 0 20px 55px rgba(47, 44, 91, .09); overflow: hidden; }
.app-header { display: flex; align-items: center; gap: 16px; padding: 34px 38px 30px; }
.brand-mark { width: 48px; height: 48px; display: grid; place-items: center; color: white; background: var(--purple); border-radius: 14px; font-size: 26px; font-weight: 700; box-shadow: 0 8px 17px rgba(104,87,232,.25); }
.eyebrow { margin: 0 0 3px; color: var(--purple); font-size: 11px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
h1, h2 { font-family: 'Plus Jakarta Sans', sans-serif; }
h1 { margin: 0; font-size: 27px; letter-spacing: -.04em; }
.task-form { display: flex; gap: 10px; padding: 0 38px 30px; border-bottom: 1px solid var(--line); }
.task-form input { min-width: 0; flex: 1; border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; color: var(--ink); background: #fafaff; outline: none; font: inherit; transition: .2s; }
.task-form input:focus { border-color: var(--purple); box-shadow: 0 0 0 3px rgba(104,87,232,.12); background: white; }
.add-button { border: 0; border-radius: 10px; padding: 0 20px; color: white; background: var(--purple); cursor: pointer; font: 600 14px 'DM Sans', sans-serif; transition: .2s; }
.add-button:hover { background: var(--purple-dark); transform: translateY(-1px); }
.list-heading { display: flex; align-items: center; justify-content: space-between; padding: 25px 38px 14px; }
h2 { margin: 0; font-size: 16px; letter-spacing: -.02em; }
.task-count { color: var(--muted); font-size: 13px; font-weight: 500; }
.task-count span:first-child { color: var(--purple); font-weight: 700; }
.tasks-area { min-height: 245px; padding: 0 22px 24px; }
.task-list { margin: 0; padding: 0; list-style: none; }
.task { display: flex; align-items: center; gap: 13px; margin: 4px 0; padding: 14px 16px; border-radius: 12px; transition: background .2s; }
.task:hover { background: #f8f8fd; }
.complete-control { width: 21px; height: 21px; flex: 0 0 21px; border: 2px solid #cfd1df; border-radius: 7px; color: white; background: transparent; cursor: pointer; display: grid; place-items: center; font-size: 13px; font-weight: 700; transition: .2s; }
.task[data-completed="true"] .complete-control { border-color: var(--purple); background: var(--purple); }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 15px; }
.task[data-completed="true"] .task-text { color: #a1a5b5; text-decoration: line-through; }
.delete-button { width: 30px; height: 30px; border: 0; border-radius: 8px; color: #aeb1c0; background: transparent; cursor: pointer; font-size: 20px; line-height: 1; opacity: 0; transition: .2s; }
.task:hover .delete-button, .delete-button:focus { opacity: 1; }
.delete-button:hover { color: #e25d72; background: #fff0f2; }
.empty-state { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 210px; text-align: center; }
.empty-icon { width: 47px; height: 47px; display: grid; place-items: center; margin-bottom: 12px; border-radius: 50%; color: var(--purple); background: #f0efff; font-size: 23px; }
.empty-title { margin: 0 0 5px; font-weight: 700; }
.empty-copy { margin: 0; color: var(--muted); font-size: 13px; }
.privacy-note { margin: 18px 0 0; color: #a0a4b6; text-align: center; font-size: 12px; }
.privacy-note span { margin-right: 5px; color: #72c69a; font-size: 9px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 520px) { .app-shell { padding-top: 25px; } .app-header, .task-form { padding-left: 22px; padding-right: 22px; } .list-heading { padding-left: 22px; padding-right: 22px; } .add-button { padding: 0 14px; } }

