const form = document.getElementById('task-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const emptyState = document.getElementById('empty-state');
const count = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.getElementById('count-label');

let tasks = [];

function updateCount() {
  const remaining = tasks.filter(task => !task.completed).length;
  count.textContent = remaining;
  countLabel.textContent = remaining === 1 ? 'task left' : 'tasks left';
}

function render() {
  list.replaceChildren();
  emptyState.hidden = tasks.length > 0;

  tasks.forEach(task => {
    const item = document.createElement('li');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const complete = document.createElement('button');
    complete.type = 'button';
    complete.className = 'complete-control';
    complete.dataset.testid = 'task-complete';
    complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
    complete.textContent = task.completed ? '✓' : '';
    complete.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', 'Delete task');
    remove.textContent = '×';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(current => current.id !== task.id);
      render();
    });

    item.append(complete, text, remove);
    list.appendChild(item);
  });
  updateCount();
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();

